def is_majority(arr, n, target):
    import math
    if n == 0:
        return False
    first = 0
    last = n - 1
    while first <= last:
        mid = (first + last) // 2
        if arr[mid] == target:
            left = mid
            while left >= 0 and arr[left] == target:
                left -= 1
            right = mid
            while right < n and arr[right] == target:
                right += 1
            count = right - left - 1
            return count > n // 2
        elif arr[mid] < target:
            first = mid + 1
        else:
            last = mid - 1
    return False
